style.css:
@-moz-document domain("slashdot.org") {
/* ---------- palette ----------
     base bg            #14181d
     elevated surface   #1c2128
     header/footer      #0d1117
     border subtle      #262c33   component #2d333b
     text primary       #e6edf3   body #c4cdd6   muted #8b949e
     link/accent        #5fb0e6   hover #9bd4ff
     Slashdot green      brand teal-green, adapted: #3ca58f surfaces / #6fd8be text
     score highlight     #6fd8be   score dimmed #8b949e
  */

  :root { color-scheme: dark; }

  html, body {
    background: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* base text + generic containers */
  body, .grid_24, #firehose, #slashboxes, #firehoselist,
  article.fhitem, .fhitem, .body, header, footer, section, aside, .novote, div {
    color: #c4cdd6;
  }

  /* soften every light border */
  * { border-color: #262c33 !important; }

  /* ---------- links ---------- */
  a, a:link, a:visited { color: #5fb0e6 !important; }
  a:hover { color: #9bd4ff !important; }

  /* ---------- masthead / logo ---------- */
  /* keep the Slashdot SVG logo visible on dark */
  #logo, .logo, h1#slashdot_org, #slashdot_org { filter: none; }

  /* top navigation / masthead — keep the iconic Slashdot green identity,
     deepened so it sits on the dark palette (the two green bars) */
  .nav-wrap, #main-top-nav-wrapper, nav.nav-user, nav.nav-primary, .nav-primary,
  #topbar, #user-bar {
    background: #0c3433 !important;
    color: #e6edf3 !important;
  }
  .nav-secondary-wrap, nav.nav-secondary {
    background: #0a2826 !important;
    color: #cdd9d6 !important;
  }
  /* all links inside both masthead bars: light + readable on the deep green */
  .nav-wrap a, #main-top-nav-wrapper a, .nav-user a, .nav-secondary-wrap a,
  .nav-secondary a, .nav-primary a, #user-bar a,
  .nav-wrap span, .nav-secondary-wrap .nav-label,
  .nav-wrap .nav-label { color: #e6edf3 !important; }
  .nav-wrap a:hover, .nav-secondary-wrap a:hover, .nav-primary a:hover { color: #9be7d6 !important; }
  /* The masthead has TWO hover fills: a deep teal (#004d4d) everywhere, and a burnt
     orange (#b7590b) on the Firehose "All" tab and on every Topics-row link. The mint
     hover colour above reads 6.8:1 on the teal but only 3.3:1 on the orange (native is
     white, 4.7:1) — a hover state no load-time scan reaches. Both orange surfaces, at a
     specificity that clears the (0,2,1) mint rule. */
  .nav-site > li .filter-firehose a:hover,
  .nav-secondary-wrap .nav-secondary li > a:hover,
  .nav-secondary .nav-secondary-list li > a:hover { color: #ffffff !important; }
  /* "Firehose" / "or" / "Topics:" / "Follow us:" small labels. The site paints these
     `#00c2c2` with `cursor: default` — the cyan IS the not-a-link affordance. The
     blanket masthead-link rules above are (0,2,0) and outranked a bare `.nav-label`
     (0,1,0), so every label flattened to the same near-white as the real links and
     "Firehose" looked as clickable as "Stories". Match the wrapper specificity. */
  .nav-label, li.nav-label,
  .nav-wrap li.nav-label, .nav-secondary-wrap li.nav-label,
  .nav-wrap .nav-label, .nav-secondary-wrap .nav-label { color: #7fd4cf !important; }

  /* ---------- story listing cards (firehose) ---------- */
  article.fhitem, .fhitem,
  article.fhitem-story, article.deals-rail, article.nosort, #slashdot_deals {
    background: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }

  /* the iconic green story-title bar — keep the Slashdot green identity, tuned for dark.
     h2.firehose is the firehose/user-submission title bar (separate from h2.story);
     it ships a light-grey #ececec→#cdcdcd gradient with black text — the green
     `background` shorthand here also clears that gradient. */
  h2.story, .story, .fhtitle, article .story,
  h2.firehose, article header h2.firehose {
    background: #14463d !important;
    color: #e6edf3 !important;
    border-color: #1d5d50 !important;
  }
  h2.story a, .story a, .story-title, .story-title a,
  h2.story span, .story span.no,
  h2.firehose a, h2.firehose span.story-title { color: #e6edf3 !important; }
  /* source link inside the green bar — the "(source.com)" flag that follows the
     title. `h2.story a` / `h2.firehose a` above are (0,1,2) and outrank a bare
     `a.story-sourcelnk` (0,1,1), so the link flattened to the same near-white as
     the title on every card. Match the bar-scoped specificity so its distinct
     teal survives (covers the submission page's .submission-sourcelnk too). */
  a.story-sourcelnk, .story-sourcelnk,
  h2.story a.story-sourcelnk, h2.firehose a.story-sourcelnk,
  h2.story a.submission-sourcelnk, h2.firehose a.submission-sourcelnk,
  .story a.story-sourcelnk, .story a.submission-sourcelnk { color: #8fd9c8 !important; }

  /* comment-count bubble */
  .comment-bubble { background: #0d1117 !important; color: #e6edf3 !important; }
  .comment-bubble a { color: #e6edf3 !important; }

  /* Related-Links / prev-next comment-count bubbles: the classic Slashdot count
     "flag" is a rounded inner <span> (#e5e5e5, dark-grey #7d7d7d text) with a
     .slant pointer triangle — both hardcoded light grey. Audit-blind (each bubble
     is ~20px wide, under the light-surface size threshold). Darken the bubble +
     tail and lift the number to a readable link-blue. */
  .cmntcnt > span, .cmntcnt_large > span,
  span.cmntcnt > span, span.cmntcnt_large > span {
    background-color: #0d1117 !important;
    color: #9bd4ff !important;
  }
  .cmntcnt .slant, .cmntcnt_large .slant,
  .bmrelatedlist .slant { background-color: #0d1117 !important; }

  /* story details bar (views / byline / dept / time) */
  .details, .story-details, div.details {
    background: #161b22 !important;
    color: #9aa4ad !important;
    border-color: #262c33 !important;
  }
  .story-views, .sodify, .story-byline, .dept-text, .story-details,
  time, span.otherdetails, .by, .byby, .uid, .writes, small {
    color: #9aa4ad !important;
  }
  .story-byline a, .details a, .by a { color: #5fb0e6 !important; }

  /* topic / type icons + popularity beaker — keep popularity red semantic but soften */
  .icon-beaker.pop1, span.icon-beaker { color: #e06c6c !important; }
  .type, .topic, .sd-info-block, .sd-key-firehose-id { color: #8b949e !important; }

  /* story body copy */
  .body, div.body, .p, div.p, .intro, .article .body {
    color: #c4cdd6 !important;
    background: transparent !important;
  }

  /* ---------- comment thread (the key surface) ---------- */
  #comments, #commentwrap, .commentwrap, #commentlisting,
  .comment, li.comment, .cw, .commentBox, .commentstatus, .commentSub {
    background: transparent !important;
    color: #c4cdd6 !important;
  }

  /* each comment wrapper sits on an elevated card */
  .cw, div.cw {
    background: #1c2128 !important;
    border-color: #262c33 !important;
  }

  /* comment title bar — green identity, white-ish title */
  .commentTop, div.commentTop {
    background: transparent !important;
  }
  .commentTop h4, .comment h4, .title h4 {
    background: #14463d !important;
    color: #e6edf3 !important;
  }
  .commentTop h4 a, .comment h4 a, .title h4 a { color: #e6edf3 !important; }

  /* score label: highlighted (white on green) vs dimmed (gray) */
  .score, span.score { color: #e6edf3 !important; }
  .score a, .score .opt { color: #e6edf3 !important; }
  /* keep mod-label readability inside the green bar */
  .commentTop h4 .score, .commentTop h4 .score a, .commentTop h4 .score .opt {
    color: #cfeee4 !important;
  }

  /* comment details / metadata line (was light-gray bg) */
  .details, div.details, .comment .details {
    background: #161b22 !important;
    color: #9aa4ad !important;
    border-color: #262c33 !important;
  }
  .comment .by, .comment .uid, .comment .otherdetails,
  .comment .writes, .comment .byby, .comment time { color: #9aa4ad !important; }
  .comment .by a, .comment .uid a { color: #5fb0e6 !important; }

  /* comment body text */
  .commentBody, div.commentBody, .commentBody p, .commentBody div {
    color: #c4cdd6 !important;
    background: transparent !important;
  }

  /* reply / parent / share controls */
  a.btn.link, .commentSub a, .menu a, a.reply {
    color: #6fd8be !important;
  }
  a.btn.link:hover, .commentSub a:hover { color: #9bead5 !important; }

  /* share popover — make opaque dark (was translucent light) */
  .comment_share, .comment_share.sharethis-0, span.au {
    background: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }
  .comment_share a, .slashpop { color: #5fb0e6 !important; }

  /* moderation / quoted text / code inside comments */
  .commentBody blockquote, blockquote, .quote {
    background: #161b22 !important;
    border-left: 3px solid #2d333b !important;
    color: #c4cdd6 !important;
  }
  .commentBody code, .commentBody pre, code, pre, tt {
    background: #0d1117 !important;
    color: #a5d6ff !important;
    border-color: #2d333b !important;
  }
  .commentBody i, .commentBody em { color: #c4cdd6 !important; }

  /* comment controls box / display options / threshold */
  .commentControlBox, #display-options, #commentControlBox,
  .ccw-score-label, .morelink, .commentControl {
    background: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }
  .ccw-score-label, .ccw-score-label * { color: #c4cdd6 !important; }
  .morelink, .morelink a { color: #5fb0e6 !important; }

  /* comment-threshold slider (#ccw widget): the Full/Abbreviated/Hidden zone panels
     are hardcoded light (full #669898, abbreviated #b2cbcb, Hidden pure #fff) — all
     audit-blind (short/nested, colored from a cross-origin sheet via two-id
     !important rules). Remap to a teal→dark scale that keeps the zone distinction. */
  #ccw-body #ccw-full-panel, #ccw #ccw-full-panel { background-color: #3ca58f !important; }
  #ccw-body #ccw-abbr-panel, #ccw #ccw-abbr-panel { background-color: #27645a !important; }
  #ccw-body #ccw-hide-panel, #ccw #ccw-hide-panel { background-color: #2d333b !important; }
  /* the two draggable thumbs (.ccwa/.ccwb) paint their light #eee fill as a
     background-IMAGE gradient, so a background-color override alone leaves them
     white; they are 11px wide, under every size-filtered scan. */
  .ccwa, .ccwb { background-image: none !important; }
  #commentwrap .slant { background-color: #1c2128 !important; }

  /* ---------- sidebars / boxes (Firehose / Popular / Polls) ---------- */
  .block, .slashbox, aside.block, #links-sidebar, #slashboxes > div {
    background: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }
  .boxhead, .block .title, .blockTitle, h3.title, h4.title,
  header#slashdot_deals-title, header#poll-title, header#mostdiscussed-title,
  header#srandblock-title, #slashboxes header, .block > header, aside header {
    background: #0d1117 !important;
    color: #e6edf3 !important;
    border-color: #262c33 !important;
  }
  #slashboxes header, #slashboxes header *, .block > header,
  .block > header * { color: #e6edf3 !important; }
  #slashboxes header a, .block > header a { color: #9bd4ff !important; }
  /* a sponsored (Nativo) sidebar block nests a real story-title bar inside the block
     header, and the link rule above — (1,0,2) — outranks `h2.story a` (0,1,2), so that
     title landed link-blue on the brown ad bar while the identical bar in the main
     column stayed near-white. Match the header scope. */
  #slashboxes header h2.story a, .block > header h2.story a,
  #slashboxes header h2.story span, .block > header h2.story span {
    color: #e6edf3 !important;
  }

  /* the "Powered By" credit in the Slashdot Deals sidebar block is a 200x35 anchor whose
     `sf-logo.png` background bakes a light-grey plate behind dark glyphs (no alpha), so
     it renders as a bright bar on every page carrying that block. A raster cannot be
     recoloured, but the art is monochrome, so inverting it gives light glyphs on a dark
     plate. The masthead/footer Slashdot marks are SVGs that are already white — leave
     them alone (`#logo`/`.logo` keep `filter: none` above). */
  #sf-logo a, div#sf-logo a { filter: invert(1) !important; }
  /* the Deals block's content wrapper is a hardcoded #fff; it only gets laid out once the
     deals feed returns items, so a load-time scan sees a zero-size (or display:none) node */
  .deals-wrapper, div.deals-wrapper { background-color: #1c2128 !important; }

  /* user profile bio card (#user_bio renders on #e6e6e6 → bio text would land on light) */
  article#user_bio, #user_bio {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }
  #user_bio a { color: #5fb0e6 !important; }

  /* /~user/achievements is the only page that loads `u2.ssl.css`, and every rule in
     it was uncovered: each row is two tiles — `.v` (the count, #ccc) and `.n` (the
     label, #eee) — and each paints its fill TWICE, once as `background` and again as
     a `background-image` gradient, so a background-color override alone leaves the
     light gradient on top. They also carry a `rgb(185,185,185) 0 1px 5px` shadow (no
     colour audit sees a shadow) and the count `span.math`/`sup` is hardcoded #000.
     Result: a full page of white cards with our light-grey label text on them. */
  div.achievements ul li div .v {
    background-color: #21262d !important;
    background-image: none !important;
    box-shadow: none !important;
  }
  div.achievements ul li div .n {
    background-color: #1c2128 !important;
    background-image: none !important;
    box-shadow: none !important;
  }
  div.achievements ul li span.math,
  div.achievements ul li span.math sup,
  div.achievements ul li sup { color: #e6edf3 !important; }

  /* user-page comment/submission list tables (~/comments) ship a white table
     background; the td cells get darkened by the neutralizer but the header
     row's <th> cells are transparent → the white leaks through as a bright strip
     (audit-blind: the th itself scans transparent). Darken the table + header. */
  table.data, table.listComments, table.data.listComments {
    background-color: #14181d !important;
  }
  table.data th, table.listComments th {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border-color: #262c33 !important;
  }
  table.data td, table.listComments td { border-color: #262c33 !important; }

  /* BOTH site sheets ship a global `table { background: white }`. The rules above
     only covered table.data / table.listComments, so every bare <table> stayed
     white — the whole Hall of Fame page rendered our light text on pure white.
     `table thead tr th` also ships #363636 text with a white text-shadow, and
     `tr.even` cells a whitesmoke zebra stripe. */
  table { background-color: #14181d !important; }
  table thead th, table thead tr th {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    text-shadow: none !important;
  }
  table tbody tr.even td, table tbody tr.even th { background-color: #1c2128 !important; }

  /* ---------- search / filter / inputs ---------- */
  input[type="text"], input[type="search"], input[type="password"],
  input[type="email"], input[name="fhfilter"], textarea, select, #search input {
    background: #0d1117 !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
    /* header search input draws a light (#f5f5f5) inset box-shadow that paints
       a silvery fill our background can't cover; appearance:auto adds native chrome */
    box-shadow: none !important;
    -webkit-appearance: none !important;
    appearance: none !important;
  }
  input[type="text"]::placeholder, input[type="search"]::placeholder,
  input[name="fhfilter"]::placeholder, textarea::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }
  /* every <select> lost its drop-down arrow. The site already sets `appearance:none`
     itself, so there is no UA caret to fall back on — it draws its own teal one as
     `background-image: url(arrow-down.png)` at `97% 50%`, and the `background:`
     SHORTHAND above resets background-image to none. Result: the search page's
     "Order by" / "Author" / "Threshold" controls render as plain boxes that no longer
     read as dropdowns (a colour audit sees nothing; the field is correctly dark).
     Redraw the caret in the theme's brand teal instead of re-fetching the site asset. */
  select {
    background-image: url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='14' height='9' viewBox='0 0 14 9'%3E%3Cpath fill='%236fd8be' d='M1.4 0 7 5.6 12.6 0 14 1.4 7 8.4 0 1.4Z'/%3E%3C/svg%3E") !important;
    background-position: right 8px center !important;
    background-repeat: no-repeat !important;
    padding-right: 28px !important;
  }
  /* buttons — text-shadow:none clears the site's `text-shadow: white 0 1px`
     on submit inputs and .btn, which outlines every glyph on a dark fill */
  input[type="submit"], input[type="button"], button, .btn, a.button {
    background: #21262d !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
    text-shadow: none !important;
  }
  input[type="submit"]:hover, button:hover, .btn:hover { background: #2d333b !important; }
  /* disabled controls: the site paints them `background: rgb(207,207,207) !important`
     from `button[disabled=disabled], input:disabled` — (0,1,1), which outranks the
     `.btn` fill above, so the "Archived Discussion" button shipped a near-white
     label on light grey. Match that specificity and give it a real disabled look. */
  button[disabled], button[disabled="disabled"], input:disabled, input[disabled] {
    background: #1c2128 !important;
    color: #6e7681 !important;
    border-color: #2d333b !important;
  }

  /* form validation messages: `.error`/`.notice`/`.success` are one site rule block
     shipping a light pastel fill with dark ink (#FBE3E4/#8a1f11, #FFF6BF/#514721,
     #E6EFC2/#264409). Every instance is `display:none` until a form fails, so no
     load-time scan walks one — the live case is `div.replyto_msg.notice` in the
     comment reply form. `.forums .*` are the same panels on the forum skin. */
  .error, .notice, .success, .replyto_msg,
  .forums .error, .forums .notice, .forums .success {
    background: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .error, .error p, .forums .error { color: #ff9492 !important; }
  .notice, .notice p, .replyto_msg, .replyto_msg p, .forums .notice { color: #e3b341 !important; }
  .success, .success p, .forums .success { color: #6fd8be !important; }
  .error a, .notice a, .success a, .replyto_msg a { color: #9bd4ff !important; }

  /* ---------- story submission form ---------- */
  /* header + subtitle were near-black (#2e2e2e / #676767) on the dark bg */
  .sd-form-header, .sd-brand-color { color: #6fd8be !important; }
  #form-wrapper hgroup p, #form-wrapper > hgroup > p { color: #9aa4ad !important; }
  /* the "You must be logged in…" notice well rendered on #f1f1f1 */
  .sd-well, p.sd-well {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }
  .sd-well a { color: #5fb0e6 !important; }

  /* ---------- footer ---------- */
  footer#fhft, #fhft, footer#ft, #ft {
    background: #0d1117 !important;
    background-image: none !important;
    color: #9aa4ad !important;
    border-color: #262c33 !important;
  }
  footer a, #fhft a, #ft a { color: #5fb0e6 !important; }

  /* ---------- modals / overlays ---------- */
  /* header Login popover uses id #embbeded_login_modal (site's spelling) and
     ships a near-white rgba(255,255,255,.95) panel — the theme's modal
     selectors didn't cover it. Darken the panel + its bold field labels. */
  .modal-box, #modal_box, #modal-box, .modal, #embbeded_login_modal {
    background: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  #embbeded_login_modal label, #embbeded_login_modal b,
  #embbeded_login_modal strong, #embbeded_login_modal .login-title {
    color: #e6edf3 !important;
  }
  #embbeded_login_modal a { color: #6fd8be !important; }

  /* the footer's "Privacy Choices" (#ccpa-modal) and "Cookie Choices" (.modal-box) panels
     are `.modal-content`, hardcoded #fefefe — a class none of the modal selectors above
     covered, so the whole opt-out text rendered our light grey ON white. Both ship in the
     DOM of EVERY page but stay display:none until the footer link is clicked, so no
     load-time scan reaches them. `#ccpa-modal` also sits INSIDE `#ft`, and our own
     `#ft a` (1,0,1) outranks `a.button.green` (0,2,1) — hence link-blue labels on the
     teal opt-out CTAs. The cookie panel's action bar is a bare `<footer>` at #f4f4f4. */
  .modal-content, .modal-content-ccpa, .modal-box footer, .modal-content footer {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  #ccpa-modal b, #ccpa-modal h2, #ccpa-modal h3, .modal-content h2 { color: #e6edf3 !important; }
  #ccpa-modal a.button.green, #ccpa-modal .button.green { color: #ffffff !important; }
  /* the panel's × is #aaa and the site DARKENS it to #000 on hover — an invert on dark */
  #ccpa-modal .close, .modal-content .close { color: #8b949e !important; }
  #ccpa-modal .close:hover, .modal-content .close:hover { color: #e6edf3 !important; }

  /* box-shadows the site drew for a white page read as a bright HALO on dark, and no
     colour/background audit sees a shadow at all: the selected "Comments Filter" tab
     carries `0 -1px 2px #ccc`, the comment Share popover `1px 1px 4px #bbb`, and this
     Login popover a 15px #666 glow around the whole panel. */
  ul.besttabslist li.active { box-shadow: 0 -1px 2px rgba(0, 0, 0, 0.6) !important; }
  .comment_share, .comment_share.sharethis-0 {
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.6) !important;
  }
  #embbeded_login_modal { box-shadow: 0 1px 15px rgba(0, 0, 0, 0.7) !important; }
  /* #modal_box's header strip is two hardcoded pure-white spans (`.fadeout` +
     `.fadeoutfade`) carrying a white 11px glow, and `#modal-p > .pref` /
     `#modal_box_content .pref` come from the same site rule. The panel itself was
     already dark, so the strip shipped as a full-width WHITE band across its top.
     The nodes live in the DOM but stay display:none until a modal opens. */
  #modal_box .fadeout, #modal_box .fadeoutfade,
  #modal-p > .pref, #modal_box_content .pref {
    background: #1c2128 !important;
    box-shadow: none !important;
  }

  /* dimmed / abbreviated (low-score) comments — keep them muted but legible
     (site dims these to #7d7d7d via an id-scoped rule, so match its specificity).
     Scope every selector to the oneline's OWN wrapper (`> .cw`): a collapsed parent
     can hold EXPANDED (`li.comment.full`) replies whose `.cw` is under a sibling
     `<ul>`, so a loose `.oneline .commentBody` descendant leaked down and dimmed a
     full, black-bodied reply to the same muted grey as a genuine low-score line. */
  #commentlisting .oneline > .cw .commentBody,
  #commentlisting .oneline > .cw .commentBody p,
  #commentlisting .oneline > .cw .commentBody div,
  .comment.oneline > .cw .commentBody, .oneline > .cw .commentBody,
  .oneline > .cw .commentBody *, li.comment.oneline > .cw .commentBody {
    color: #9aa4ad !important;
  }
  #commentlisting .oneline > .cw .commentBody a,
  .oneline > .cw .commentBody a { color: #5fb0e6 !important; }

  /* comment score-selector widget + "You may like" header bar (light-grey #e1e1e1).
     Only the #newa2footerv2 h3's are natively light — a bare `h3` here boxed every
     heading on the site (poll questions, "Most Votes" dividers). */
  .grid_3, .sc, span.sc, #newa2footerv2 h3, .ccwa, .ccwb, .tag-menu-admin, menu#tag-menu,
  menu#feedback-menu, .nf, input.fno {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }
  .grid_3 a, .sc a, h3 a, .ccwa a, .ccwb a { color: #5fb0e6 !important; }

  /* per-story "apply tags" popup (.tag-menu div): ships a pure-white box with a
     white/light-grey CSS-triangle pointer built from ::before (outer #e4e1e1) +
     ::after (inner #fff) borders — audit-blind (display:none until the tags line
     is clicked; the theme only covered menu#tag-menu / .tag-menu-admin, not the
     plain .tag-menu class). Darken the box and recolor the pointer triangle. */
  .tag-menu, div.tag-menu {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }
  .tag-menu::before { border-bottom-color: #2d333b !important; }
  .tag-menu::after { border-bottom-color: #1c2128 !important; }
  /* a tag chip and a moderation-reason item keep a light #d4e3e3 HOVER fill (the reasons
     menu declares it `!important`), which our light link colour then sits on at ~1.5:1.
     A hover state is invisible to every load-time scan. */
  .tag-bar .tag:hover, .details .reasons-menu a:hover {
    background-color: #2d333b !important;
    color: #9bd4ff !important;
  }

  /* ---------- generic light-surface neutralizer ---------- */
  /* native-ad / newsletter / "you may like" / comment-filter sections render
     on a hardcoded white or light-grey bg → darken to the base */
  section, section.grid_24, .ad-blocked-newsletter, .ntv-preview-img-wrapper,
  .sticky-cta, .sticky-wrapper, .sticky-left, .sticky-gradient,
  .thisday-yr, .commentControlBox, .a2 {
    background-color: #14181d !important;
  }
  /* the ONLY natively light <label>s are the poll option rows (#eee); the ONLY
     natively light <td>s are the "This day on Slashdot" cells (#e6e6e6). Painting
     the bare element types instead left dark chips behind every form label
     (login modal) and every transparent table cell. */
  #pollBooth label { background-color: #21262d !important; }
  /* each option row is a click target and the site lifts it on hover
     (`.poll-group-form label:hover { background-color: #ecf2f2 }`); the id-scoped
     fill above is (1,1,0) !important and outranks it, so the whole booth lost its
     only hover affordance — a state no load-time scan reaches. */
  #pollBooth label:hover, .poll-group-form label:hover {
    background-color: #2d333b !important;
  }
  table.thisday-tb td { background-color: #14181d !important; }
  section.bq, .bq, blockquote.msg, blockquote,
  .bq p, blockquote.msg p, section.bq p {
    background-color: #161b22 !important;
    color: #c4cdd6 !important;
  }
  /* the fortune / quote text + any leftover black body copy on dark */
  .bq *, blockquote.msg *, .msg, td, label, .legend, h3 {
    color: #c4cdd6 !important;
  }
  /* the year column keeps a subtle teal accent (native #006666). The td-neutralizer
     `table.thisday-tb td` (0,1,2) above outranks a bare `.thisday-yr` (0,1,0), so the
     year cell flattened to the base grey; match its specificity to restore the tint. */
  .thisday-yr,
  table.thisday-tb td.thisday-yr { background-color: #0a2826 !important; color: #cdd9d6 !important; }

  /* comment-filter / "Comments Filter:" bar + its links */
  .commentControlBox, .commentControlBox *, #commentControlBox,
  .legend, .legend * { color: #c4cdd6 !important; }
  .commentControlBox a, .legend a { color: #5fb0e6 !important; }

  /* poll cards (More Polls list) — the vote-count + byline footer rows render
     on a hardcoded light-grey (#f2f2f2) with dark (#4d4d4d) text */
  .info-meta, .info-byline, .info-meta *, .info-byline * {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }
  .info-meta a, .info-byline a { color: #5fb0e6 !important; }
  /* the divider between the two footer rows is drawn as a `border-bottom: 1px solid
     #ccc` on `.info-meta::after` — the blanket `* { border-color }` reset never
     matches a pseudo-element, so a bright line survived on every poll card */
  .info-meta::after, .info-byline::after { border-color: #262c33 !important; }

  /* poll-feed card headers keep the site's brand teal (#006666); the global link
     colour landed mid-blue on it at 2.9:1 */
  .feed-header a, header.feed-header a, .feed-header h2 a { color: #ffffff !important; }
  .feed-header a:hover, header.feed-header a:hover { color: #9be7d6 !important; }

  /* poll RESULT bars (after voting): the unfilled track ships a hardcoded light
     grey (#e1e1e1) — audit-blind (only ~20px tall). Darken the track; keep the
     orange vote fill (brand semantic) and make the overflow label text legible
     on both the orange fill and the dark track. */
  .poll-bar-bg { background-color: #21262d !important; }
  .poll-bar-text { color: #e6edf3 !important; }
  /* The "N votes / P%" label is one fixed-width run that crosses BOTH the fill and
     the track, so a single colour has to work on each. On the site's light track the
     native dark label managed that; on our dark track only a light label does — and
     light-on-#ff8c3f is 2.2:1. Deepen the fill (still unmistakably the brand orange)
     so the white label clears 4.5:1 wherever it lands. */
  .poll-bar-bg .poll-bar-fill, .poll-bar-fill { background-color: #a85a1c !important; }
  /* "voting booth" / "other polls": the site ships these as white-on-orange chips
     (`.polls-results a { color: white !important; background-color: orange !important }`).
     That rule is (0,1,1) — exactly the specificity of our own `a:link`, so the later
     sheet won and the labels came out link-blue on orange (~1.5:1). Restore the
     site's white label at anchor specificity. */
  .polls-results a, .polls-results a:link, .polls-results a:visited,
  .polls-results a:hover { color: #ffffff !important; }

  /* ---------- brand / semantic buttons (keep their color, fix text) ---------- */
  .btn-success, a.btn-success, .nel-button, .btn-polls, button.btn-polls,
  .btn-primary, input.button {
    color: #ffffff !important;
  }
  /* Every entry above that is a BARE class is (0,1,0) and loses to our own
     `a, a:link, a:visited { color: #5fb0e6 }` (0,1,1) whenever the control is an
     <a> — so a solid coloured button rendered as a link keeps its fill but takes the
     page link-blue. Live proof: `/polls` renders "view results" / "view more" as
     `a.btn-polls`, i.e. blue on the brand orange at 1.6:1, while the sibling
     `button.btn-polls` ("vote now") is correctly white. Restate the whole family in
     anchor form (incl. :link/:visited/:hover, which each beat a bare class too). */
  a.btn-polls, a.btn-polls:link, a.btn-polls:visited, a.btn-polls:hover,
  a.nel-button, a.nel-button:link, a.nel-button:visited, a.nel-button:hover,
  a.btn-primary, a.btn-primary:link, a.btn-primary:visited, a.btn-primary:hover,
  a.btn-danger, a.btn-danger:link, a.btn-danger:visited, a.btn-danger:hover,
  a.btn-warning, a.btn-warning:link, a.btn-warning:visited, a.btn-warning:hover,
  a.btn-info, a.btn-info:link, a.btn-info:visited, a.btn-info:hover,
  a.btn-success:link, a.btn-success:visited, a.btn-success:hover {
    color: #ffffff !important;
  }
  /* slashdot's default SOLID buttons ship the brand teal fill (#057e7e) with white
     text — its primary-action affordance. The generic grey `.btn` rule above (a
     deliberate neutral-button choice) swallowed the ones carrying no Bootstrap
     modifier: the comment "Post" reply CTA (.btn.first) and "Load All Comments"
     (#d2loadall) came out the same grey as any neutral button, erasing the primary
     hierarchy the masthead's green "Submit" (.btn-success) keeps. Restore a brand-primary
     teal on these primary CTAs (placed before the Bootstrap variants so a semantic
     .btn-danger/.btn-success still wins any tie).
     CONSTRAINT: these two sit ON the comment bar, whose own native gradient runs
     #006666 -> #004242, so the fill must stay LIGHTER than #006666 or the button has no
     edge against the bar at all. The id selectors here also outrank the generic
     `.btn:hover`, so the hover state has to be restated. */
  a.btn.first, input.btn.first, button.btn.first, .btn.first,
  #d2loadall, a#d2loadall, #d2reply, a#d2reply {
    background-color: #0b7c7c !important;
    border-color: #0e9494 !important;
    color: #ffffff !important;
  }
  a.btn.first:hover, input.btn.first:hover, button.btn.first:hover, .btn.first:hover,
  #d2loadall:hover, a#d2loadall:hover, #d2reply:hover, a#d2reply:hover {
    background-color: #0e9494 !important;
  }
  /* The comment bar is rendered TWICE — once in `#d2header`, once inside the page
     footer `#fhft`. Our own footer rule `footer a, #fhft a, #ft a { color: #5fb0e6 }`
     is (1,0,1) and outranks `a.btn.first` (0,2,1), so the bottom "Post" shipped
     link-blue on the teal fill (2.1:1) while the identical top one was white. Any
     primary CTA that can appear in either bar needs an id-scoped restatement. */
  #fhft a.btn.first, #ft a.btn.first, #fhft a#d2loadall, #ft a#d2loadall,
  #fhft a#d2reply, #ft a#d2reply, #fhft a.btn-success, #ft a.btn-success {
    color: #ffffff !important;
  }
  /* …and keep their FILL too. The generic `.btn` rule above is !important at the
     same (0,1,0) specificity, so it swallowed every Bootstrap modifier: the green
     "Submit" CTA in the masthead came out the same grey as a plain button, and the
     danger/warning/info states lost their meaning. Restore the site's own fills at
     (0,2,0) so the outcome no longer depends on stylesheet order. */
  .btn.btn-success, a.btn-success, button.btn-success {
    background-color: #5cb85c !important;
    border-color: #4cae4c !important;
  }
  .btn.btn-primary, a.btn-primary, button.btn-primary {
    background-color: #006666 !important;
    border-color: #025c5c !important;
  }
  .btn.btn-danger, a.btn-danger, button.btn-danger {
    background-color: #d9534f !important;
    border-color: #d43f3a !important;
  }
  .btn.btn-warning, a.btn-warning, button.btn-warning {
    background-color: #f0ad4e !important;
    border-color: #eea236 !important;
  }
  .btn.btn-info, a.btn-info, button.btn-info {
    background-color: #5bc0de !important;
    border-color: #46b8da !important;
  }
  /* …and their HOVER. Each fill above is (0,2,0) — exactly the specificity of the site's
     own `.btn-success:hover` etc. — and ships later, so every solid button lost its hover
     response entirely: the masthead's green "Submit" measured identical resting vs hovered
     while natively it darkens to #449d44. A hover state is invisible to every load-time
     scan; a native-vs-themed hover diff is what surfaces it. */
  .btn.btn-success:hover, a.btn-success:hover, button.btn-success:hover {
    background-color: #449d44 !important;
  }
  .btn.btn-primary:hover, a.btn-primary:hover, button.btn-primary:hover {
    background-color: #035553 !important;
  }
  .btn.btn-danger:hover, a.btn-danger:hover, button.btn-danger:hover {
    background-color: #c9302c !important;
  }
  .btn.btn-warning:hover, a.btn-warning:hover, button.btn-warning:hover {
    background-color: #ec971f !important;
  }
  .btn.btn-info:hover, a.btn-info:hover, button.btn-info:hover {
    background-color: #31b0d5 !important;
  }
  /* prev/next pager buttons sat on white. Natively the active one is the brand teal
     and the disabled one a faded grey; the theme flattened BOTH to the same grey with
     blue link text (an `a:link` at 0,1,1 even beat this rule's colour), so a disabled
     "Newer" looked exactly as clickable as an active "Older". Keep the active/clickable
     ones grey + blue, but give the disabled one a genuinely muted, non-clickable look
     (matching the theme's disabled-button style) at anchor specificity. */
  a.prevnextbutact, .prevnextbutact, .pad-btns a {
    background: #21262d !important;
    color: #9bd4ff !important;
    border-color: #2d333b !important;
  }
  a.prevnextbutdis, .prevnextbutdis {
    background: #171b21 !important;
    color: #6e7681 !important;
    border-color: #262c33 !important;
  }

  /* floating sticky-CTA banner — opaque dark, readable text */
  .sticky-cta, .sticky-cta *, .sticky-wrapper, .sticky-wrapper * {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }
  .sticky-cta a, .sticky-wrapper a { color: #5fb0e6 !important; }

  /* native-ad "Sponsored / Featured Content" label (Nativo classes) */
  .ntv-ad-label, .ntv-sponsored, .nel-sponsored,
  span.sponsored, .sponsored-label {
    background-color: #2d333b !important;
    color: #c4cdd6 !important;
  }
  /* The disclaimer WRAPPER is natively transparent — painting it invented a grey
     box on the brown bar. The visible chip is the dynamic-suffix `ntv_link…`
     anchor, natively a lighter brown (#a66934) with a white label: that tint IS
     the ad-disclosure signal, so deepen it rather than flattening it to grey. */
  .ntv-sponsored-disclaimer { background-color: transparent !important; }
  /* the sidebar copy of the chip sits inside `.block > header`, whose (0,2,1) link
     rule outranks a bare `a[class*=…]` — hence the extra header-scoped selectors */
  a[class*="ntv_link"], header a[class*="ntv_link"],
  .block > header a[class*="ntv_link"], #slashboxes header a[class*="ntv_link"],
  h2 a[class*="ntv_link"] {
    background-color: #6b4321 !important;
    color: #ffffff !important;
  }

  /* selected pager / tab list-items (load-more-comments, Related Links, All)
     render with a hardcoded white highlight → make them a dark active state.
     ONLY the selected ones: an unselected li.fleft is natively transparent, so
     matching the bare class boxed every footer day-tab. */
  li.fleft.selected, ul.fleft li.selected, nav ul li.selected,
  .btmrel, a.btmrel, li.btmrel, .filter-firehose li.selected {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  li.fleft a, li.fleft.selected a, .btmrel a, a.btmrel,
  .filter-firehose li.selected a, nav ul li.selected a {
    color: #9bd4ff !important;
  }
  /* the "Get N More Comments" button */
  #more_comments_button, .nbutton, span.nbutton {
    background-color: #21262d !important;
    color: #9bd4ff !important;
    border-color: #2d333b !important;
  }
  /* the id above is (1,0,0) and outranks the generic `.btn:hover`, so this control —
     natively a link that darkens #006b6b -> #002f2f — had no hover response at all.
     Restate at id specificity. */
  #more_comments_button:hover, .nbutton:hover, span.nbutton:hover {
    background-color: #2d333b !important;
    color: #cfe8ff !important;
  }

  /* prev/next page links sitting on the light-grey article footer band */
  .grid_24.f a, aside.st a, .st .links a { color: #9bd4ff !important; }

  /* active comment-filter tab ("All") — white highlight → dark active state */
  #comments li.active, .commentControlBox li.active, .filter-firehose li.active,
  ul.fleft li.active, li.active {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }
  #comments li.active a, .commentControlBox li.active a,
  li.active a { color: #9bd4ff !important; }

  /* sidebar topic-list nav header bar (#ccc) + its prev/next links */
  .tlnav, h5.tlnav, .tlnav-head {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border-color: #262c33 !important;
  }
  .tlnav a, h5.tlnav a { color: #9bd4ff !important; }

  /* ---------- real-element CSS triangles ---------- */
  /* The fortune-quote pointer is a border triangle (transparent sides + a white
     bottom border), so the blanket `* { border-color }` above fills all four sides
     into a solid blob. Restore the transparent sides and follow the quote's bg. */
  blockquote.msg .slant, section.bq .slant {
    background: none !important;
    border-color: transparent transparent #161b22 !important;
  }
  /* The "Most Votes" / "Most Comments" divider rules are ::before/::after top
     borders (#e6e6e6) — `*` never matches pseudo-elements, so they stayed light. */
  .center-line span::before, .center-line span::after { border-top-color: #262c33 !important; }
  /* comment-count bubble tail: a ::after triangle that keeps the site's original
     #1e2329 while we repaint the bubble itself */
  span.comment-bubble::after { border-top-color: #0d1117 !important; }

  /* ---------- header user dropdown (.menu) ---------- */
  /* The .menu container is natively transparent and absolutely positioned; the
     visible panel is the .menu-list inside it, hardcoded #fff. Its pointer is a
     pair of pseudo border triangles (#aaa outer / #fff inner). */
  .menu, .menu-share { background: transparent !important; }
  .menu .menu-list, .menu-share .menu-list {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }
  .menu .menu-list li { border-top-color: #2d333b !important; }
  .menu::before, .menu-share::before { border-bottom-color: #2d333b !important; }
  .menu::after, .menu-share::after { border-bottom-color: #1c2128 !important; }

  /* user-profile tab pointer: a rotated #e5e5e5 <span> diamond beside the active tab */
  nav#u2tabs li.active > span, #u2tabs li.active span { background-color: #21262d !important; }

  /* ---------- the rest of the "active tab" family ----------
     One site rule paints EVERY active tab `background: rgb(229,229,229)`, labels it
     #999 and adds a WHITE `text-shadow` halo; a second rotates a #e5e5e5 <span> into
     a diamond pointer under it. The theme only covered the `li` forms and only the
     #u2tabs diamond, so the story-archive / profile / journal tabs shipped a white
     glow around every glyph and a bright diamond below. The span-shaped siblings
     (#fh-paginate, .preftab, .hoftab, .linkCommentPage) were never covered at all. */
  #story_archive_opts .active, #story_archive_opts_year .active,
  #fh-paginate > span.active, .pref .preftab.active, .mhof .hoftab.active,
  #friendsmenu li.active, .linkCommentPage .active, #formtabs .active,
  ul.menu li.selected, #hofnew .active {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }
  #story_archive_opts .active, #story_archive_opts_year .active,
  #fh-paginate > span.active, .pref .preftab.active, .mhof .hoftab.active,
  #friendsmenu li.active, .linkCommentPage .active, #formtabs .active,
  ul.menu li.selected, #hofnew .active, #hofnew .active a,
  li.active, li.active a, li.selected, li.selected a,
  span.preftab.active a, ul.menu li.selected a {
    text-shadow: none !important;
  }
  /* the rotated diamond pointer under each active tab */
  #story_archive_opts .active > span, #story_archive_opts_year .active > span,
  #archpagin .active > span, .hoftab.active > span, .pref .preftab.active > span,
  #formtabs .active > span, #friendsmenu li.active > span,
  ul.menu li.selected > span, li.active > span {
    background-color: #21262d !important;
  }

  /* /archive.pl day markers: `.archive_breaks > span` is a hardcoded #e5e5e5 pill
     and `> .slant` its rotated pointer — 13 bright chips down the page, both under
     every light-surface size floor */
  nav.abdb .archive_breaks > span, .archive_breaks > span {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }
  nav.abdb .archive_breaks > .slant, .archive_breaks > .slant {
    background-color: #21262d !important;
  }

  /* collapsed ("oneline") comments have NO title bar natively — the site sets
     `background:none` on their h4 — so the green title-bar rule above painted a
     pill behind every "Re:" link. Pin to the oneline's OWN wrapper (`> .cw`): an
     EXPANDED reply nested under a collapsed parent keeps its `.cw` beneath a
     sibling `<ul>`, so a loose descendant here erased that full reply's green
     Score title bar too. */
  #comments .oneline > .cw .commentTop h4, #comments .oneline > .cw .title h4 { background: none !important; }
  #comments .oneline > .cw .commentTop h4 a, #comments .oneline > .cw .title h4 a { color: #6fd8be !important; }

  /* sponsored / native-ad story bars ship a brown (#6d4634) title bar instead of the
     editorial green — keep that disclosure distinction rather than flattening it */
  article[class*="article-nel-"] h2.story, article[class*="article-nel-"] .story {
    background: #3d2a1f !important;
    border-color: #5a3f2e !important;
  }

  /* ---------- polls list feed ---------- */
  /* the "Older"/"Newer" pager buttons keep a hardcoded #ecf2f2 fill (57x36 — below
     the light-surface scan's size floor) and our link colour then lands blue on it */
  .btn-view-more, a.btn-view-more {
    background-color: #21262d !important;
    border-color: #2d333b !important;
    color: #9bd4ff !important;
  }
  .btn-view-more a, .btn-view-more a:visited { color: #9bd4ff !important; }
  .btn-view-more:hover, .btn-view-more a:hover { background-color: #2d333b !important; }
  /* "Posted on … | N votes" metadata is #7d7d7d — readable on the site's white,
     only 4.3:1 on our base */
  .content-list li span, .content-list li span i { color: #9aa4ad !important; }

  /* ---------- /faq ---------- */
  /* The FAQ's left index is a `#accordion` list whose every `li` is a hardcoded
     #f4f4f4 — a full-height white column beside the (correctly dark) answers. The
     expanded item keeps its own white on `a.about` / `.aboutOver` (#ddd). */
  #accordion li, #accordion li a.about, #accordion.faq-menu li ul li {
    background-color: #1c2128 !important;
  }
  #accordion li a.about:hover, .aboutOver { background-color: #262c33 !important; }
  /* the "^ Top" back-links: the caret is an <i> the site colours #006666 (1.9:1 on
     our base) with a #1e2329 hover — the anchor rule never reaches it, an <i> is not
     an <a>. Same story for the FAQ answer-body carets. */
  .faq-listing > div i, .faq-listing div i,
  .faq-listing > div i:hover, .faq-listing div i:hover { color: #6fd8be !important; }

  /* ---------- comment-search results (search.pl?op=…) ---------- */
  /* the "Search Results" section heading is a bare #3c4040 <h2> — 1.3:1 on our
     dark results panel (the result-item <h2>s below stay readable because their
     text lives in a link child; this section header is the one plain-text one).
     Scoped to the search container so a bare content h2 elsewhere is untouched. */
  .temp-results-spacing h2, .temp-results-spacing .main-content h2 {
    color: #e6edf3 !important;
  }

  /* ---------- /software/ + /content/ (the SourceForge-powered shell) ----------
     The "Business Software" directory and the "Thought Leadership" blog are top-level
     nav destinations on slashdot.org but a completely different frontend, and the
     theme never covered them: the page wrapper (#f6f8f8), the article column, every
     sidebar widget and its header (#fff, the last one !important) all shipped white,
     and the widget titles — which our own base rule had already lightened — rendered
     near-white ON that white. */
  body .off-canvas-content, .off-canvas-content { background-color: #14181d !important; }
  .side-column-contents, .blog-body { background-color: transparent !important; }
  .main-content, .l-content-column .main-content, .project-body > .main-content,
  .main-content-wrapper, .l-black-n-tan .main-content-wrapper,
  .m-sidebar-widget, .m-wide-widget, .m-wide-projects-widget {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }
  /* the widget title is a bare shrink-to-fit <header>, so a dark fill here would draw a
     chip around the words rather than a bar — clear it and let the card show through */
  .m-sidebar-widget header, .m-sidebar-widget .as-header,
  .m-wide-widget header, .m-wide-widget .as-header {
    background: transparent !important;
    color: #e6edf3 !important;
  }
  .m-screenshots-display-full, .m-sub-section { background-color: #161b22 !important; }
  /* the directory's product-logo tiles are a hardcoded white card (`.show-border`) so
     every vendor logo — colour, transparent or dark — reads on light. 25 of them down
     the listing shipped as bright white squares on the dark page. Darken the tile to the
     elevated surface: transparent/colour logos gain a proper dark backdrop and the ones
     that bake their own white stay unchanged (the raster <img> is untouched). */
  .project-icon.show-border, .result-heading .project-icon,
  li.project-bsl .project-icon, .overview .project-icon { background-color: #1c2128 !important; }
  /* current-page breadcrumb crumb is a plain #333 <span> (not a link) */
  #breadcrumbs .breadcrumb_last, .breadcrumb_last { color: #9aa4ad !important; }
  /* only the page-title h1 is natively dark (#333). The directory's h3 product names are
     the site's cyan (#00c2c2 — already 8:1 on dark); the theme's blanket `h3` entry in
     the light-surface neutralizer had greyed all 25 of them, so put the cyan back. */
  .off-canvas-content h1 { color: #e6edf3 !important; }
  .off-canvas-content h3, .projects h3, .result-heading-title h3 { color: #00c2c2 !important; }
  /* the directory's PRIMARY CTA ("Learn More", 25 of them) is `.sandiego .green.button`,
     the brand cyan #00c2c2. Our generic grey `.btn/button/a.button` fill is !important
     at a lower specificity, so it beat the site's plain rule and every primary CTA came
     out the same grey as a neutral button. Restore a cyan-teal that carries the white
     label at 5:1 (the native #00c2c2 only reaches 1.9:1 under white). Same for the
     blog's teal search-submit. */
  .sandiego .green.button, a.button.green, .button.green,
  a.button.btn-masthead-cmpn-main, .btn-masthead-cmpn-main {
    background-color: #0b7c7c !important;
    border-color: #0e9494 !important;
    color: #ffffff !important;
  }
  .sandiego .green.button:hover, a.button.green:hover, .button.green:hover,
  a.button.btn-masthead-cmpn-main:hover {
    background-color: #0e9494 !important;
  }
  /* the cyan accent outlines (emphasised sections, the "blue" outline buttons) are the
     one place the blanket `* { border-color }` reset erased a real signal */
  section.m-section-emphasized, section.psp-section,
  .button.blue, a.button.blue, div.button.blue { border-color: #0e9494 !important; }
  /* the grey `.button` family ("Free Trial" = `.btn-masthead-cmpn-secondary`,
     "View Integrations" = `.sandiego .blue.button`) took the neutral fill above but no
     hover: `button:hover`/`.btn:hover` never match Foundation's `.button`, so these CTAs
     measured identical resting vs hovered while natively they lighten #006665 -> #038686.
     Keep this at (0,2,0) so the green/hollow/hollow-opaque hovers below still win. */
  a.button:hover, .button:hover, input.button:hover,
  .btn-masthead-cmpn-secondary:hover { background-color: #2d333b !important; }
  input.search-submit, .m-sidebar-widget input.search-submit {
    background-color: #0b7c7c !important;
    border-color: #0e9494 !important;
    color: #ffffff !important;
  }
  /* the product tab strip (About / Reviews / Pricing / …) is a white bar; its SELECTED
     tab is a pale mint (#dde9e8) that our light label then landed on invisibly */
  /* every tab also draws its 3px underline as a border-IMAGE (a white gradient on the
     idle tabs, the brand teal on the selected one). A border-image ignores
     border-color, so the blanket `*` reset left a bright white rule under the strip
     and, once cleared, would have left the selected tab with no indicator at all. */
  li.commercial_nav, ul.dropdown li.commercial_nav {
    background-color: #1c2128 !important;
    border-image-source: none !important;
    border-bottom-color: #262c33 !important;
  }
  /* the SELECTED tab's pale mint (#dde9e8) is painted by a (2,4,2) `!important` rule in
     the cross-origin fsdn sheet, so the class-level selector above never reached it */
  .sandiego .project-masthead #commercial-project-nav #top_nav_admin ul.dropdown li.selected,
  li.commercial_nav.selected, ul.dropdown li.commercial_nav.selected {
    background-color: #14463d !important;
    border-image-source: none !important;
    border-bottom-color: #6fd8be !important;
  }
  li.commercial_nav.selected a, li.commercial_nav.selected a span { color: #e6edf3 !important; }
  /* the review sort/filter buttons keep the brand teal (#006665) as TEXT — 1.9:1 on the
     dark page. Their fill+colour come from a (0,5,0) `!important` Foundation rule
     (`.sandiego .default.hollow-blue.hollow.button`), so match it. */
  .sandiego .default.hollow-blue.hollow.button,
  .sort-drop-down.button, .m-review-filters .sort-drop-down { color: #6fd8be !important; }
  /* the "hollow" chips (review flags such as "Review was Incentivized", whose label is
     a ::before) are #333 on transparent — invisible on dark — and their hover state
     flips to a near-white #e6ecec fill. Same (0,4,0) `!important` origin. */
  .sandiego .default.hollow.button, .sandiego .default.hollow.button::before {
    color: #c4cdd6 !important;
  }
  .sandiego .default.hollow.button svg { fill: #c4cdd6 !important; }
  .sandiego .default.hollow.button:hover, .sandiego .default.hollow.button:focus {
    background: #2d333b !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }
  .sandiego .default.hollow.button:hover svg,
  .sandiego .default.hollow.button:focus svg { fill: #e6edf3 !important; }
  /* breadcrumb " > " separators are ::before content at #666 (3.1:1) */
  #breadcrumbs li::before, nav#breadcrumbs ul li::before { color: #8b949e !important; }
  /* the mobile off-canvas menu keeps the site's own teal panel (#006665) and paints its
     items #fefefe; the global link colour landed mid-blue on that teal at 2.7:1. Only
     reachable by opening the hamburger at a narrow viewport. */
  .off-canvas a, .off-canvas a:link, .off-canvas a:visited,
  .off-canvas .menu a { color: #fefefe !important; }
  /* the mobile hamburger is a natively TRANSPARENT <button>, so the generic button fill
     drew a dark chip around its bars on the teal title bar. Narrow viewport only. */
  button.menu-icon, .title-bar-right button.menu-icon {
    background: transparent !important;
    border: 0 !important;
  }
  /* Foundation's dropdown panel is a `ul.menu`, so the transparent `.menu` rule written
     for the classic header dropdown blanked it too: the directory's open Sort menu
     ("Sponsored / Highest Rated / Most Reviews") had NO background and its items
     overlapped the listing behind them. It is natively #fefefe on #cacaca. Only exists
     once the menu is clicked open, so no load-time scan reaches it. */
  ul.menu.is-dropdown-submenu, .dropdown.menu .is-dropdown-submenu {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* both the open menu's rows and the `Sort:` trigger that opens it lost the site's only
     hover cue (#333 -> #006665) because our accent colour is already applied at rest */
  ul.menu.is-dropdown-submenu a:hover,
  .dropdown.menu .is-dropdown-submenu a:hover,
  .m-project-search-results div.sort-by a:hover, a.current-sort:hover {
    background-color: #262c33 !important;
    color: #9be7d6 !important;
  }
  /* the shell's OTHER two Foundation floating surfaces, both hardcoded #fefefe and both
     display:none until opened, so no load-time scan reaches either: `.reveal` is the
     product page's "Get Information About <product>" lead-form modal (a 600x720 white
     panel carrying our light-grey field labels and consent copy) and `.dropdown-pane` the
     five review filters (Rating / Organization Size / User's Role / …). */
  .reveal, .dropdown-pane {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .reveal h1, .reveal h2, .reveal h3, .dropdown-pane li { color: #c4cdd6 !important; }
  /* the review-filter chip's own open/hover state is `.sandiego .default.hollow-blue
     .hollow.button:hover` — one class MORE than the `.hollow` variant restated above, so
     the chip still flipped to the site's #e6ecec with black text while its pane opened. */
  .sandiego .default.hollow-blue.hollow.button:hover,
  .sandiego .default.hollow-blue.hollow.button:focus {
    background: #2d333b !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }
  /* long reviews are clamped and a `#fff` "read more" chip is laid over the bottom-right
     corner of the text (`.m-review.extended.needs-readmore .link-read-more`) */
  .link-read-more, a.link-read-more { background: #1c2128 !important; }
  /* that menu's caret is a pair of real-element border triangles (transparent sides,
     coloured top), so the blanket `* { border-color }` reset filled all four sides and it
     rendered as a solid box. `.over-triangle` exists only to notch `.triangle` against a
     white page — drop it and keep one solid light caret. */
  div.triangle, .sort-by .triangle {
    border-color: #c4cdd6 transparent transparent !important;
  }
  div.over-triangle, .sort-by .over-triangle { border-color: transparent !important; }
  /* directory pagination: the "…" gap marker is a #0a0a0a ::after (1.1:1, gone) and the
     "«/»" chevrons are ::after content that took the global link blue onto the teal
     Prev/Next buttons (2.9:1). Neither is a text node, so no colour audit sees them. */
  ul.pagination li.ellipsis::after, .pagination li.ellipsis::after {
    color: #8b949e !important;
  }
  .pagination-next a::after, .pagination-previous a::after,
  .pagination .pagination-next a::after,
  .pagination .pagination-previous a::after { color: #ffffff !important; }
  /* Foundation's `.pagination a:hover { background:#e6e6e6 }` survived every rule above
     (nothing here restates a pagination hover), so hovering a page number painted a
     near-white chip carrying our #9bd4ff link ink at ~1.5:1. Click-state only, so no
     load-time scan sees it; present on the directory AND every product review pager. */
  .pagination a:hover, .pagination button:hover,
  .pagination li a:hover, ul.pagination a:hover {
    background: #262c33 !important;
    color: #e6edf3 !important;
  }
  .pagination .disabled:hover, .pagination li.disabled a:hover {
    background: transparent !important;
  }
  /* the sponsor bar's CTA label is also ::before content, hardcoded #001e2b — on the
     dark bar it renders at 1.1:1, i.e. an invisible call-to-action */
  .sticky-cta::before, .sticky-wrapper .sticky-cta::before,
  .sticky-right .sticky-cta::before { color: #e6edf3 !important; }
  .m-heat-gradient .axis span, .m-heat-gradient .axis span.active { color: #e6edf3 !important; }
  /* the directory search box and its typeahead are `<input>` with NO type attribute,
     so every `input[type=…]` rule above missed them: white field, white placeholder */
  form.directory-search-box, .directory-search-box,
  .typeahead__container input, .typeahead__query input {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .typeahead__container input::placeholder, .typeahead__query input::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }
  /* …and the typeahead's own RESULT panel is a separate `ul.typeahead__list` at #fff.
     It only exists once you type, so no load-time scan reaches it: the "Find software
     to compare" flyout listed every product as our light grey ON white. The rows'
     selected state is already our dark `li.active`, so only the panel needs darkening. */
  ul.typeahead__list, .typeahead__list, .typeahead__result {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* the highlighted row's #f5f5f5 fill sits on the row's ANCHOR, not on the
     `li.active` our tab rules already darken, so one band stayed white */
  .typeahead__item.active > a, .typeahead__item:hover > a,
  .typeahead__list li.active > a, .typeahead__list li:hover > a {
    background-color: #2d333b !important;
  }

  /* ---------- /software/comparison/ (the side-by-side compare grid) ----------
     A page type the theme never covered. `.m-compare-table-grid .cell` ships
     `background:#fff` with 2px #057e7e side borders — 42 of them — so the whole grid
     rendered as full-height white columns carrying our light-grey copy, and the
     blanket `*` border reset had already erased the teal column outline. */
  .m-compare-table-grid .cell, .m-compare-table-grid-header .cell {
    background-color: #1c2128 !important;
    border-left-color: #0e9494 !important;
    border-right-color: #0e9494 !important;
  }
  .m-compare-table-grid .cell.col-header, .m-compare-table-grid-header .cell.col-header {
    border-top-color: #0e9494 !important;
  }
  .m-compare-table-grid .cell.col-footer, .m-compare-table-grid-header .cell.col-footer {
    border-bottom-color: #0e9494 !important;
  }
  /* the feature ticks encode presence as `path{fill:#00c2c2}` and ABSENCE as #e6ecec —
     a near-white that was the fainter of the two on the site's white cell but is the
     BRIGHTER of the two on a dark one, inverting the signal on ~400 rows. Mute the
     absent tick and keep the site's cyan for the present one. */
  .m-compare-table-grid .feature svg path,
  .m-compare-table-grid-header .feature svg path { fill: #3d444d !important; }
  .m-compare-table-grid .feature.has-feature svg path,
  .m-compare-table-grid-header .feature.has-feature svg path { fill: #00c2c2 !important; }
  /* the pros/cons headings are the same #497f81 / #cd0303 the site uses on white */
  .m-compare-table-grid .pros-cons-label.pros { color: #6fd8be !important; }
  .m-compare-table-grid .pros-cons-label.cons { color: #f08a86 !important; }
  /* the "Explore All N Integrations" CTAs are `.hollow-opaque`, which the shell paints
     `background:#fff !important` at (0,4,0) — the generic button rules never reached it */
  .sandiego .green.hollow-opaque.button, .sandiego .default.hollow-opaque.button,
  .sandiego .blue.hollow-opaque.button, .sandiego .orange.hollow-opaque.button,
  a.button.hollow-opaque, .button.hollow-opaque {
    background-color: #1c2128 !important;
    color: #6fd8be !important;
  }
}
